{% extends 'eshop/base.html' %}
{% block title %}Tài Khoản{% endblock %}
{% block content %}
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
<style>
.prof-wrap{max-width:700px;margin:2rem auto}
.prof-card{background:white;border-radius:16px;padding:1.5rem;box-shadow:0 2px 15px rgba(0,0,0,.06);margin-bottom:1.5rem}
.prof-card h3{margin:0 0 1rem;font-size:1.1rem;font-weight:800;display:flex;align-items:center;gap:8px}
.prof-card h3 i{color:#667eea}
.prof-map-wrap{overflow:hidden;border-radius:12px;border:2px solid #e8ecf1;position:relative}
#profile-map{height:300px;width:100%;z-index:1}
.prof-map-bar{display:flex;gap:.5rem;padding:10px;background:#f8f9fa;border-top:1px solid #e8ecf1}
.prof-map-bar input{flex:1;padding:8px 12px;border:2px solid #e8ecf1;border-radius:8px;font-size:.85rem;outline:none}
.prof-map-bar input:focus{border-color:#667eea}
.prof-map-btn{padding:8px 14px;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:.8rem;display:inline-flex;align-items:center;gap:4px;transition:.2s}
.prof-map-btn:hover{transform:translateY(-1px)}
.prof-map-btn-search{background:#667eea;color:white}
.prof-map-btn-gps{background:#2dce89;color:white}
.prof-addr-status{font-size:.78rem;margin-top:4px;padding:4px 0;display:flex;align-items:center;gap:4px}
.prof-addr-ok{color:#2dce89;font-weight:600}
.prof-addr-err{color:#f5365c;font-weight:600}
.prof-addr-warn{color:#fb6340;font-weight:600}
.leaflet-routing-container{display:none!important}
</style>

<div class="prof-wrap">
    <!-- Header -->
    <div class="prof-card">
        <div style="display:flex;align-items:center;gap:1rem;">
            {% if request.user.avatar %}
            <img src="{{ request.user.avatar.url }}" style="width:56px;height:56px;border-radius:50%;object-fit:cover;border:3px solid #667eea;">
            {% else %}
            <div style="width:56px;height:56px;border-radius:50%;background:linear-gradient(135deg,#667eea,#764ba2);display:flex;align-items:center;justify-content:center;color:white;font-size:1.3rem;">
                <i class="fas fa-user"></i>
            </div>
            {% endif %}
            <div style="flex:1;">
                <h2 style="font-size:1.3rem;font-weight:800;color:#2d3436;margin:0;">{% if request.user.first_name %}{{ request.user.first_name }} {{ request.user.last_name }}{% else %}{{ request.user.email }}{% endif %}</h2>
                <div style="font-size:.85rem;color:#636e72;">{{ request.user.email }}</div>
            </div>
            <a href="{% url 'eshop:logout' %}" class="btn-outline" style="font-size:.8rem;padding:8px 16px;">
                <i class="fas fa-sign-out-alt"></i> Đăng xuất
            </a>
        </div>
    </div>

    <!-- Profile Edit -->
    <div class="prof-card">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:1rem;">
            <h3><i class="fas fa-id-card"></i>Thông Tin Cá Nhân</h3>
            <button type="button" onclick="toggleEdit()" id="editBtn" class="btn-outline" style="font-size:.78rem;padding:6px 14px;">
                <i class="fas fa-pen"></i> Chỉnh sửa
            </button>
        </div>

        <!-- Display mode -->
        <div id="profileDisplay">
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;">
                <div style="grid-column:span 2;display:flex;align-items:center;gap:1rem;margin-bottom:.5rem;">
                    {% if request.user.avatar %}
                    <img src="{{ request.user.avatar.url }}" style="width:64px;height:64px;border-radius:50%;object-fit:cover;border:3px solid #667eea;">
                    {% else %}
                    <div style="width:64px;height:64px;border-radius:50%;background:linear-gradient(135deg,#667eea,#764ba2);display:flex;align-items:center;justify-content:center;color:white;font-size:1.5rem;">
                        <i class="fas fa-user"></i>
                    </div>
                    {% endif %}
                    <div>
                        <div style="font-size:1.1rem;color:#2d3436;font-weight:700;">{{ request.user.first_name }} {{ request.user.last_name }}</div>
                        <div style="font-size:.85rem;color:#636e72;">{{ request.user.email }}</div>
                    </div>
                </div>
                <div>
                    <div style="font-size:.75rem;color:#636e72;text-transform:uppercase;font-weight:700;margin-bottom:4px;">Số điện thoại</div>
                    <div style="font-size:.95rem;color:#2d3436;">{% if request.user.phone %}{{ request.user.phone }}{% else %}<span style="color:#b2bec3;">Chưa nhập</span>{% endif %}</div>
                </div>
                <div>
                    <div style="font-size:.75rem;color:#636e72;text-transform:uppercase;font-weight:700;margin-bottom:4px;">Địa chỉ</div>
                    <div style="font-size:.95rem;color:#2d3436;">{% if request.user.address %}{{ request.user.address }}{% else %}<span style="color:#b2bec3;">Chưa nhập</span>{% endif %}</div>
                </div>
            </div>
            {% if request.user.lat and request.user.lng %}
            <div style="margin-top:1rem;">
                <div class="prof-map-wrap">
                    <div id="display-map" style="height:200px;width:100%;z-index:1"></div>
                </div>
            </div>
            {% endif %}
        </div>

        <!-- Edit mode -->
        <div id="profileEdit" style="display:none;">
            <form method="post" enctype="multipart/form-data" id="profileForm">
                {% csrf_token %}
                {{ form.lat }}
                {{ form.lng }}
                <div class="form-group">
                    <label>{{ form.avatar.label }}</label>
                    <div style="display:flex;align-items:center;gap:1rem;">
                        {% if request.user.avatar %}
                        <img src="{{ request.user.avatar.url }}" style="width:48px;height:48px;border-radius:50%;object-fit:cover;">
                        {% else %}
                        <div style="width:48px;height:48px;border-radius:50%;background:#dfe6e9;display:flex;align-items:center;justify-content:center;color:#636e72;font-size:1.2rem;">
                            <i class="fas fa-camera"></i>
                        </div>
                        {% endif %}
                        {{ form.avatar }}
                    </div>
                    {% if form.avatar.errors %}
                    <div style="color:#f5365c;font-size:.8rem;margin-top:4px;">{{ form.avatar.errors.0 }}</div>
                    {% endif %}
                </div>
                <div class="form-group">
                    <label>{{ form.full_name.label }}</label>
                    {{ form.full_name }}
                    {% if form.full_name.errors %}
                    <div style="color:#f5365c;font-size:.8rem;margin-top:4px;">{{ form.full_name.errors.0 }}</div>
                    {% endif %}
                </div>
                <div class="form-group">
                    <label>{{ form.phone.label }}</label>
                    {{ form.phone }}
                    {% if form.phone.errors %}
                    <div style="color:#f5365c;font-size:.8rem;margin-top:4px;">{{ form.phone.errors.0 }}</div>
                    {% endif %}
                </div>
                <div class="form-group">
                    <label>{{ form.address.label }}</label>
                    {{ form.address }}
                    <div id="addr-status" class="prof-addr-status"></div>
                    {% if form.address.errors %}
                    <div style="color:#f5365c;font-size:.8rem;margin-top:4px;">{{ form.address.errors.0 }}</div>
                    {% endif %}
                </div>

                <!-- Map for address selection -->
                <div class="prof-map-wrap" style="margin-bottom:1rem;">
                    <div id="profile-map"></div>
                    <div class="prof-map-bar">
                        <input type="text" id="map-search-input" placeholder="Tìm địa chỉ trên bản đồ...">
                        <button type="button" class="prof-map-btn prof-map-btn-search" onclick="searchMapAddress()"><i class="fas fa-search"></i></button>
                        <button type="button" class="prof-map-btn prof-map-btn-gps" onclick="getGPSLocation()"><i class="fas fa-location-crosshairs"></i></button>
                    </div>
                </div>

                <div style="display:flex;gap:.5rem;margin-top:1rem;">
                    <button type="submit" class="btn-primary" style="padding:10px 24px;" id="saveBtn">
                        <i class="fas fa-save"></i> Lưu
                    </button>
                    <button type="button" onclick="toggleEdit()" class="btn-outline" style="padding:10px 24px;">Hủy</button>
                </div>
            </form>
        </div>
    </div>

    <!-- Password Change -->
    <div class="prof-card">
        <h3><i class="fas fa-lock"></i>Đổi Mật Khẩu</h3>
        <form method="post" id="passwordForm">
            {% csrf_token %}
            <div class="form-group">
                <label>Mật khẩu hiện tại</label>
                <input type="password" name="old_password" required class="eshop-input" placeholder="Nhập mật khẩu hiện tại">
            </div>
            <div class="form-group">
                <label>Mật khẩu mới</label>
                <input type="password" name="new_password" required minlength="8" class="eshop-input" placeholder="Tối thiểu 8 ký tự">
            </div>
            <div class="form-group">
                <label>Xác nhận mật khẩu mới</label>
                <input type="password" name="confirm_password" required minlength="8" class="eshop-input" placeholder="Nhập lại mật khẩu mới">
            </div>
            <button type="submit" class="btn-primary" name="password_change" style="padding:10px 24px;">
                <i class="fas fa-key"></i> Đổi mật khẩu
            </button>
        </form>
    </div>

    <!-- Orders -->
    <div class="prof-card">
        <h3><i class="fas fa-receipt"></i>Đơn Hàng Của Tôi</h3>
        {% if orders %}
        <table style="width:100%;border-collapse:collapse;">
            <thead>
                <tr>
                    <th style="text-align:left;padding:10px 12px;font-size:.78rem;color:#636e72;text-transform:uppercase;font-weight:700;border-bottom:2px solid #f0f2f5;">Mã ĐH</th>
                    <th style="text-align:left;padding:10px 12px;font-size:.78rem;color:#636e72;text-transform:uppercase;font-weight:700;border-bottom:2px solid #f0f2f5;">Ngày đặt</th>
                    <th style="text-align:left;padding:10px 12px;font-size:.78rem;color:#636e72;text-transform:uppercase;font-weight:700;border-bottom:2px solid #f0f2f5;">Trạng thái</th>
                    <th style="text-align:right;padding:10px 12px;font-size:.78rem;color:#636e72;text-transform:uppercase;font-weight:700;border-bottom:2px solid #f0f2f5;">Tổng</th>
                </tr>
            </thead>
            <tbody>
                {% for order in orders %}
                <tr>
                    <td style="padding:10px 12px;border-bottom:1px solid #f0f2f5;font-weight:600;color:#667eea;font-family:monospace;font-size:.85rem;">
                        <a href="{% url 'eshop:order_detail' order.order_id %}" style="color:inherit;text-decoration:none;">{{ order.order_id }}</a>
                    </td>
                    <td style="padding:10px 12px;border-bottom:1px solid #f0f2f5;font-size:.85rem;color:#636e72;">{{ order.created_at|date:'d/m/Y H:i' }}</td>
                    <td style="padding:10px 12px;border-bottom:1px solid #f0f2f5;"><span class="status-badge status-{{ order.status }}">{{ order.get_status_display }}</span></td>
                    <td style="padding:10px 12px;border-bottom:1px solid #f0f2f5;text-align:right;font-weight:700;color:#2d3436;">{{ order.total_amount|floatformat:0 }}đ</td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
        
        <!-- Pagination -->
        {% if orders.has_other_pages %}
        <div style="display:flex;justify-content:center;align-items:center;gap:8px;margin-top:1.5rem;">
            {% if orders.has_previous %}
            <a href="?page={{ orders.previous_page_number }}" style="display:flex;align-items:center;justify-content:center;width:32px;height:32px;border:1px solid #e8ecf1;border-radius:6px;text-decoration:none;color:#636e72;font-weight:600;transition:all .2s;" onmouseover="this.style.background='#f8f9fa';this.style.borderColor='#667eea';this.style.color='#667eea'" onmouseout="this.style.background='';this.style.borderColor='#e8ecf1';this.style.color='#636e72'">
                <i class="fas fa-chevron-left"></i>
            </a>
            {% endif %}

            {% for num in orders.paginator.page_range %}
                {% if orders.number == num %}
                <span style="display:flex;align-items:center;justify-content:center;width:32px;height:32px;background:#667eea;color:white;border-radius:6px;font-weight:700;">{{ num }}</span>
                {% elif num > orders.number|add:'-3' and num < orders.number|add:'3' %}
                <a href="?page={{ num }}" style="display:flex;align-items:center;justify-content:center;width:32px;height:32px;border:1px solid #e8ecf1;border-radius:6px;text-decoration:none;color:#636e72;font-weight:600;transition:all .2s;" onmouseover="this.style.background='#f8f9fa';this.style.borderColor='#667eea';this.style.color='#667eea'" onmouseout="this.style.background='';this.style.borderColor='#e8ecf1';this.style.color='#636e72'">{{ num }}</a>
                {% endif %}
            {% endfor %}

            {% if orders.has_next %}
            <a href="?page={{ orders.next_page_number }}" style="display:flex;align-items:center;justify-content:center;width:32px;height:32px;border:1px solid #e8ecf1;border-radius:6px;text-decoration:none;color:#636e72;font-weight:600;transition:all .2s;" onmouseover="this.style.background='#f8f9fa';this.style.borderColor='#667eea';this.style.color='#667eea'" onmouseout="this.style.background='';this.style.borderColor='#e8ecf1';this.style.color='#636e72'">
                <i class="fas fa-chevron-right"></i>
            </a>
            {% endif %}
        </div>
        <div style="text-align:center;font-size:.85rem;color:#636e72;margin-top:0.5rem;">
            Trang {{ orders.number }}/{{ orders.paginator.num_pages }} ({{ orders.paginator.count }} đơn hàng)
        </div>
        {% endif %}
        {% else %}
        <div class="empty-state" style="padding:2rem;">
            <i class="fas fa-box-open"></i>
            <h3>Chưa có đơn hàng</h3>
            <a href="{% url 'eshop:products' %}" class="btn-primary" style="margin-top:1rem;display:inline-block;">Mua sắm ngay</a>
        </div>
        {% endif %}
    </div>
</div>

<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
// Address validation state
let addrValid = {% if request.user.lat and request.user.lng %}true{% else %}false{% endif %};
let addrChecked = {% if request.user.lat and request.user.lng %}true{% else %}false{% endif %};

function updateAddrStatus() {
    const el = document.getElementById('addr-status');
    const addrInput = document.getElementById('id_address');
    const saveBtn = document.getElementById('saveBtn');

    if (!addrInput.value.trim()) {
        // Empty address is allowed (field is optional)
        el.innerHTML = '';
        addrValid = true;
        saveBtn.disabled = false;
        saveBtn.style.opacity = '1';
        return;
    }

    if (!addrChecked) {
        el.innerHTML = '<i class="fas fa-exclamation-circle"></i> Vui lòng chọn vị trí trên bản đồ hoặc nhấn định vị GPS để xác thực địa chỉ';
        el.className = 'prof-addr-status prof-addr-warn';
        addrValid = false;
    } else if (addrValid) {
        el.innerHTML = '<i class="fas fa-check-circle"></i> Địa chỉ đã được xác thực trên bản đồ';
        el.className = 'prof-addr-status prof-addr-ok';
    } else {
        el.innerHTML = '<i class="fas fa-times-circle"></i> Địa chỉ không tìm thấy trên bản đồ! Vui lòng chọn vị trí hợp lệ';
        el.className = 'prof-addr-status prof-addr-err';
    }

    saveBtn.disabled = !addrValid;
    saveBtn.style.opacity = addrValid ? '1' : '.5';
}

// Form submit validation
document.getElementById('profileForm').addEventListener('submit', function(e) {
    const addrInput = document.getElementById('id_address');
    if (addrInput.value.trim() && !addrValid) {
        e.preventDefault();
        updateAddrStatus();
    }
});

function toggleEdit() {
    const display = document.getElementById('profileDisplay');
    const edit = document.getElementById('profileEdit');
    const btn = document.getElementById('editBtn');
    if (edit.style.display === 'none') {
        edit.style.display = 'block';
        display.style.display = 'none';
        btn.style.display = 'none';
        setTimeout(function(){ editMap.invalidateSize(); }, 200);
        updateAddrStatus();
    } else {
        edit.style.display = 'none';
        display.style.display = 'block';
        btn.style.display = 'inline-block';
    }
}

// ===== DISPLAY MAP (read-only) =====
{% if request.user.lat and request.user.lng %}
(function(){
    var m = L.map('display-map',{center:[{{ request.user.lat }},{{ request.user.lng }}],zoom:16,zoomControl:false,attributionControl:false});
    setTimeout(function(){m.invalidateSize()},200);
    L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png',{subdomains:'abcd',maxZoom:20}).addTo(m);
    var icon=L.divIcon({className:'',html:'<div style="background:linear-gradient(135deg,#2196F3,#03A9F4);width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:white;font-size:14px;border:3px solid white;box-shadow:0 3px 10px rgba(0,0,0,.3)"><i class="fas fa-home"></i></div>',iconSize:[34,34],iconAnchor:[17,17]});
    L.marker([{{ request.user.lat }},{{ request.user.lng }}],{icon:icon}).addTo(m).bindPopup('<b>Vị trí của bạn</b>').openPopup();
    m.dragging.disable(); m.scrollWheelZoom.disable(); m.doubleClickZoom.disable();
})();
{% endif %}

// ===== EDIT MAP =====
var editMap = L.map('profile-map',{center:[10.7769,106.7009],zoom:13,zoomControl:true});
setTimeout(function(){editMap.invalidateSize()},300);
L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png',{subdomains:'abcd',maxZoom:20}).addTo(editMap);

var pinIcon = L.divIcon({className:'',html:'<div style="background:linear-gradient(135deg,#FF9800,#FFC107);width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:white;font-size:14px;border:3px solid white;box-shadow:0 3px 10px rgba(0,0,0,.3)"><i class="fas fa-map-pin"></i></div>',iconSize:[34,34],iconAnchor:[17,17]});
var currentMarker = null;

// Initialize marker if user has saved location
{% if request.user.lat and request.user.lng %}
currentMarker = L.marker([{{ request.user.lat }},{{ request.user.lng }}],{icon:pinIcon,draggable:true}).addTo(editMap);
editMap.setView([{{ request.user.lat }},{{ request.user.lng }}],16);
currentMarker.on('dragend',function(e){ reverseGeocode(e.target.getLatLng().lat,e.target.getLatLng().lng); });
{% endif %}

// Click map to pin
editMap.on('click',function(e){
    if(currentMarker) editMap.removeLayer(currentMarker);
    currentMarker = L.marker(e.latlng,{icon:pinIcon,draggable:true}).addTo(editMap);
    currentMarker.on('dragend',function(ev){ reverseGeocode(ev.target.getLatLng().lat,ev.target.getLatLng().lng); });
    reverseGeocode(e.latlng.lat,e.latlng.lng);
});

function reverseGeocode(lat,lng){
    fetch('https://nominatim.openstreetmap.org/reverse?format=json&lat='+lat+'&lon='+lng+'&zoom=18&addressdetails=1&countrycodes=vn')
    .then(function(r){return r.json()})
    .then(function(data){
        if(data && data.display_name){
            var addr = data.display_name;
            document.getElementById('id_address').value = addr;
            document.getElementById('id_lat').value = lat;
            document.getElementById('id_lng').value = lng;
            addrValid = true;
            addrChecked = true;
            updateAddrStatus();
            currentMarker.bindPopup('<b>Vị trí đã chọn</b><br><span style="font-size:.75rem">'+addr.substring(0,80)+'...</span>').openPopup();
        } else {
            addrValid = false;
            addrChecked = true;
            document.getElementById('id_lat').value = '';
            document.getElementById('id_lng').value = '';
            updateAddrStatus();
        }
    })
    .catch(function(){
        addrValid = false;
        addrChecked = true;
        updateAddrStatus();
    });
}

// Search address on map
function searchMapAddress(){
    var q = document.getElementById('map-search-input').value.trim();
    if(!q) return;
    fetch('https://nominatim.openstreetmap.org/search?format=json&q='+encodeURIComponent(q)+'&countrycodes=vn&limit=1')
    .then(function(r){return r.json()})
    .then(function(data){
        if(data && data.length>0){
            var lat=parseFloat(data[0].lat), lng=parseFloat(data[0].lon);
            if(currentMarker) editMap.removeLayer(currentMarker);
            currentMarker = L.marker([lat,lng],{icon:pinIcon,draggable:true}).addTo(editMap);
            currentMarker.on('dragend',function(e){ reverseGeocode(e.target.getLatLng().lat,e.target.getLatLng().lng); });
            editMap.setView([lat,lng],17);
            document.getElementById('id_address').value = data[0].display_name;
            document.getElementById('id_lat').value = lat;
            document.getElementById('id_lng').value = lng;
            addrValid = true;
            addrChecked = true;
            updateAddrStatus();
            currentMarker.bindPopup('<b>'+q+'</b>').openPopup();
        } else {
            addrValid = false;
            addrChecked = true;
            document.getElementById('id_lat').value = '';
            document.getElementById('id_lng').value = '';
            updateAddrStatus();
        }
    })
    .catch(function(){
        addrValid = false;
        addrChecked = true;
        updateAddrStatus();
    });
}

// GPS location
function getGPSLocation(){
    if(!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(function(p){
        var lat=p.coords.latitude, lng=p.coords.longitude;
        if(currentMarker) editMap.removeLayer(currentMarker);
        currentMarker = L.marker([lat,lng],{icon:pinIcon,draggable:true}).addTo(editMap);
        currentMarker.on('dragend',function(e){ reverseGeocode(e.target.getLatLng().lat,e.target.getLatLng().lng); });
        editMap.setView([lat,lng],17);
        reverseGeocode(lat,lng);
    },function(){
        alert('Không thể lấy vị trí GPS. Vui lòng cho phép quyền vị trí.');
    });
}

// Watch for manual address input changes
document.getElementById('id_address').addEventListener('input', function(){
    // If user manually types an address, require map validation
    if(this.value.trim()){
        addrChecked = false;
        addrValid = false;
        updateAddrStatus();
    } else {
        // Empty address is fine
        addrValid = true;
        addrChecked = true;
        updateAddrStatus();
    }
});

// Enter key in search input
document.getElementById('map-search-input').addEventListener('keydown', function(e){
    if(e.key==='Enter'){ e.preventDefault(); searchMapAddress(); }
});
</script>
{% endblock %}
